    Registration = apps.get_model('services', 'ServiceRegistration')
    for service in Service.objects.filter(kind='DISTRIBUTION'):
        service.default_tickets = service.sessions_per_registration or 1
        if service.name.startswith('Épicerie'):
            service.max_bookings_per_week = 1
            if service.session_capacity is None:
                service.session_capacity = 18
        service.save()
        if service.session_weekday is None:
            continue
        slot = Slot.objects.create(
            service=service, weekday=service.session_weekday, start_time=service.session_start,
            end_time=service.session_end, capacity=service.session_capacity)
        for session in Session.objects.filter(service=service):
            session.schedule_slot = slot
            session.original_date = session.date
            if session.capacity is None:
                session.capacity = service.session_capacity
            session.save()
    for reg in Registration.objects.filter(service__kind='DISTRIBUTION'):
        reg.tickets = max(reg.bookings.count(), reg.service.default_tickets)
        reg.save()


